zationId } = context()\n    const back = {\n      returnTo: toSsoReturnPath(returnTo ?? router.currentRoute.value.fullPath),\n      origin: window.location.origin\n    }\n    if (organizationId) {\n      return ssoStartUrl({\n        organizationId,\n        email: knownEmail.value ?? undefined,\n        ...back\n      })\n    }\n    if (!knownEmail.value) return undefined\n    return ssoStartUrl({ email: knownEmail.value, ...back })\n  }\n\n  async function continueWithSso() {\n    leaving.value = true\n    const ssoTarget = ssoDestination()\n    const target =\n      ssoTarget ??\n      router.resolve({ name: 'cloud-login', query: SSO_ENTRY_OPEN_QUERY }).href\n    try {\n      if (authStore.currentUser) await authStore.logout()\n    } catch (error) {\n      leaving.value = false\n      toastErrorHandler(error)\n      return\n    }\n    if (ssoTarget) trackSsoContinueClicked('cloud_app')\n    window.location.assign(target)\n  }\n\n  return { knownEmail, leaving, continueWithSso }\n}\n"],"mappings":"ySAAA,IAAM,EAAwB,iBACxB,EAAsB,uBAQ5B,SAAgB,gBAAgB,EAA0B,CACxD,IAAM,EAAM,IAAI,IAAI,EAAU,oBAAoB,EAIlD,OAHI,EAAI,SAAS,QAAQ,OAAQ,EAAE,IAAM,EAGlC,GAAG,IAAsB,EAAI,SAAS,EAAI,OAFxC,CAGX,CCFA,SAAgB,mBAAmB,EAAmC,CACpE,IAAM,EAAS,EAAU,EACnB,EAAY,EAAa,EACzB,CAAE,qBAAsB,EAAiB,EACzC,EAAa,MAAe,EAAQ,CAAC,CAAC,OAAS,EAAU,SAAS,EAClE,EAAU,EAAI,EAAK,EAGzB,SAAS,gBAAqC,CAC5C,GAAM,CAAE,WAAU,kBAAmB,EAAQ,EACvC,EAAO,CACX,SAAU,gBAAgB,GAAY,EAAO,aAAa,MAAM,QAAQ,EACxE,OAAQ,OAAO,SAAS,MAC1B,EACA,GAAI,EACF,OAAO,EAAY,CACjB,iBACA,MAAO,EAAW,OAAS,IAAA,GAC3B,GAAG,CACL,CAAC,EAEE,KAAW,MAChB,OAAO,EAAY,CAAE,MAAO,EAAW,MAAO,GAAG,CAAK,CAAC,CACzD,CAEA,eAAe,iBAAkB,CAC/B,EAAQ,MAAQ,GAChB,IAAM,EAAY,eAAe,EAC3B,EACJ,GACA,EAAO,QAAQ,CAAE,KAAM,cAAe,MAAO,CAAqB,CAAC,CAAC,CAAC,KACvE,GAAI,CACE,EAAU,aAAa,MAAM,EAAU,OAAO,CACpD,OAAS,EAAO,CACd,EAAQ,MAAQ,GAChB,EAAkB,CAAK,EACvB,MACF,CACI,GAAW,EAAwB,WAAW,EAClD,OAAO,SAAS,OAAO,CAAM,CAC/B,CAEA,MAAO,CAAE,aAAY,UAAS,eAAgB,CAChD"}"""

